def solve_langford(n):
    length = 2 * n
    seq = [0] * length

    def backtrack(v):
        if v == 0:
            return True

        for i in range(length - (v + 1)):
            if seq[i] == 0 and seq[i + v + 1] == 0:
                seq[i] = v
                seq[i + v + 1] = v
                if backtrack(v - 1):
                    return True
                seq[i] = 0
                seq[i + v + 1] = 0
        return False

    if backtrack(n):
        return seq
    else:
        return None

result = solve_langford(6)
print(result)
